import random

def predict(x, w, b):
    return w * x + b

def mse(y_true, y_pred):
    return sum((yt - yp) ** 2 for yt, yp in zip(y_true, y_pred)) / len(y_true)

x_data = [1, 2, 3, 4]
y_data = [3, 5, 7, 9]   # true relationship: y = 2x + 1

w, b = 0.0, 0.0
loss = mse(y_data, [predict(x, w, b) for x in x_data])

for step in range(500):
    candidate_w = w + random.uniform(-0.05, 0.05)
    candidate_b = b + random.uniform(-0.05, 0.05)
    candidate_loss = mse(y_data, [predict(x, candidate_w, candidate_b) for x in x_data])
    if candidate_loss < loss:
        w, b, loss = candidate_w, candidate_b, candidate_loss

print(round(w, 2), round(b, 2), round(loss, 4))   # w near 2.0, b near 1.0, loss near 0

