exercises.solutionCode:
def predict(x, w, b):
    return w * x + b

def mse(y_true, y_pred):
    return sum((yt - yp) ** 2 for yt, yp in zip(y_true, y_pred)) / len(y_true)

x = [1, 2, 3, 4]
y = [3, 5, 7, 9]

w, b = 0.0, 0.0

for step in range(5):
    w += 0.5
    y_pred = [predict(xi, w, b) for xi in x]   # recomputed fresh with the CURRENT w
    loss = mse(y, y_pred)
    print(f"step {step}: w={w:.2f}, loss={loss:.3f}")
